#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, "gpio-output-demo", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output (initial value 0).\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main loop: toggle every 5 seconds */
    while (keep_running) {
        int value = (gpiod_line_get_value(line) < 0) ? -1 : 0;
        if (value < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d value: %d\n", GPIO_LINE_OFFSET, value);
        fflush(stdout);

        /* Toggle the output */
        ret = gpiod_line_set_value(line, value ^ 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        /* Sleep for the poll interval, checking keep_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released. Exiting.\n", GPIO_LINE_OFFSET);
    fflush(stdout);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous */
    uint16_t config = 0x4003;
    if (i2c_write_reg16(fd, CONFIG_REG, config) < 0) {
        goto cleanup;
    }

    /* Allow first conversion to complete (128 SPS -> ~8 ms) */
    usleep(10000);

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, CONVERSION_REG, &raw) < 0) {
            goto cleanup;
        }
        int16_t signed_val = (int16_t)raw;
        printf("ADC Value: %d\n", signed_val);
        fflush(stdout);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define MLX90614_ADDR 0x5a
#define I2C_BUS "/dev/i2c-1"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_mlx90614(int fd, float *ambient, float *object) {
    uint16_t raw_ambient, raw_object;
    if (i2c_read_reg16(fd, 0x06, &raw_ambient) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, 0x07, &raw_object) < 0) {
        return -1;
    }
    *ambient = (float)raw_ambient * 0.02f - 273.15f;
    *object = (float)raw_object * 0.02f - 273.15f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient, object;
        if (read_mlx90614(fd, &ambient, &object) < 0) {
            fprintf(stderr, "Error reading MLX90614: %s\n", strerror(errno));
            break;
        }
        printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
        fflush(stdout);
        sleep(POLL_INTERVAL_SEC);
    }

    close(fd);
    return EXIT_SUCCESS;
}

