#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 500
#define INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or no root privileges?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d: frequency=%d Hz, range=%d, duty=%d\n",
           PWM_PIN, PWM_FREQUENCY, PWM_RANGE, PWM_DUTY_CYCLE);
    fflush(stdout);

    while (running) {
        gpioDelay(INTERVAL_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define POLL_INTERVAL_SEC 60
#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_US 0.0343
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static double measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec ts_start, ts_end;
    long long elapsed_us;
    int timeout;

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(2);

    /* Send 10 us trigger pulse */
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) {
            fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
            return -1.0;
        }
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (no object detected or sensor absent)\n");
            return -1.0;
        }
        usleep(1);
    }

    /* Wait for echo falling edge (timeout) */
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) {
            fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
            return -1.0;
        }
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout (object out of range or sensor absent)\n");
            return -1.0;
        }
        usleep(1);
    }

    elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000LL +
                 (ts_end.tv_nsec - ts_start.tv_nsec) / 1000LL;

    double distance = (double)elapsed_us * SOUND_SPEED_CM_PER_US / 2.0;
    if (distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm exceeds max (%.0f cm)\n", distance, MAX_DISTANCE_CM);
        return -1.0;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get trigger line */
    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get echo line */
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        double distance = measure_distance(trigger, echo);

        if (distance < 0) {
            fprintf(stderr, "Error: measurement failed, exiting.\n");
            goto cleanup;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("Program terminated cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128SPS (0x0080)
#define ADS1115_CONFIG_CQUE_NONE (0x0003)

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16(reg=0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16: read data failed: %s\n", strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t cfg = ADS1115_CONFIG_OS_BEGIN
                 | ADS1115_CONFIG_MUX_AIN0_GND
                 | ADS1115_CONFIG_PGA_4_096V
                 | ADS1115_CONFIG_MODE_SINGLE
                 | ADS1115_CONFIG_DR_128SPS
                 | ADS1115_CONFIG_CQUE_NONE;
    return i2c_write16(fd, ADS1115_REG_CONFIG, cfg);
}

static int ads1115_read(int fd, int16_t *out) {
    uint16_t raw;
    if (i2c_read16(fd, ADS1115_REG_CONV, &raw) < 0)
        return -1;
    *out = (int16_t)raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(fd) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X\n", ADS1115_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        int16_t raw;
        if (ads1115_read(fd, &raw) < 0) {
            fprintf(stderr, "Read failed; continuing\n");
        } else {
            printf("Analog reading: %d\n", raw);
            fflush(stdout);
        }
        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, "gpio-output-demo", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output (initial value 0).\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main loop: toggle every second until interrupted */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("GPIO %d: %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        /* Toggle the output */
        val = val ? 0 : 1;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        /* Sleep for 1 second, checking keep_running every 100 ms */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(100000);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define BCM_PIN 18
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value LOW (0) */
    if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        /* Set HIGH */
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value(HIGH)");
            goto cleanup;
        }
        printf("Cycle %d: HIGH\n", i + 1);
        fflush(stdout);
        sleep(CYCLE_DELAY_SEC);

        if (!keep_running) break;

        /* Set LOW */
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value(LOW)");
            goto cleanup;
        }
        printf("Cycle %d: LOW\n", i + 1);
        fflush(stdout);
        sleep(CYCLE_DELAY_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous */
    uint16_t config = 0x4003;
    if (i2c_write_reg16(fd, CONFIG_REG, config) < 0) {
        goto cleanup;
    }

    /* Allow first conversion to complete (128 SPS -> ~8 ms) */
    usleep(10000);

    uint16_t raw;
    if (i2c_read_reg16(fd, CONVERSION_REG, &raw) < 0) {
        goto cleanup;
    }

    printf("ADS1115 AIN0: %d\n", (int16_t)raw);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 2)");
        goto cleanup;
    }
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("gpiod_chip_get_line (GPIO 3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 initialized as outputs (initial state LOW).\n");
    fflush(stdout);

    /* Main loop: toggle every 5 seconds */
    while (keep_running) {
        int val2 = gpiod_line_get_value(line2);
        int val3 = gpiod_line_get_value(line3);

        if (val2 < 0 || val3 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", val2, val3);
        fflush(stdout);

        /* Toggle values */
        int new2 = (val2 == 0) ? 1 : 0;
        int new3 = (val3 == 0) ? 1 : 0;

        if (gpiod_line_set_value(line2, new2) < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, new3) < 0) {
            perror("gpiod_line_set_value (GPIO 3)");
            goto cleanup;
        }

        /* Sleep for 5 seconds, checking keep_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("GPIO lines released. Exiting.\n");
    }
    return ret;
}

