#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Configure ADS1115: single-shot, AIN0 vs GND, +/-4.096V, 128 SPS */
    uint16_t config = 0x8483;
    if (i2c_write_reg16(fd, CONFIG_REG, config) < 0) {
        goto cleanup;
    }

    /* Wait for conversion to complete (128 SPS -> ~8 ms; use 10 ms) */
    usleep(10000);

    for (int i = 0; i < 3 && running; i++) {
        uint16_t raw;
        if (i2c_read_reg16(fd, CONVERSION_REG, &raw) < 0) {
            goto cleanup;
        }
        int16_t value = (int16_t)raw;
        printf("Reading %d: %d\n", i + 1, value);
        fflush(stdout);
        if (i < 2) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 6
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};
static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    int cycle = 0;
    while (keep_running && cycle < 256) {
        for (int i = 0; i < NUM_PINS; i++) {
            int val = (cycle % 2 == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", pins[i]);
                goto cleanup;
            }
        }
        printf("Cycle %d: all pins set to %s\n", cycle, (cycle % 2 == 0) ? "HIGH" : "LOW");
        fflush(stdout);
        cycle++;
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

