static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL, *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line17 || !line18 || !line27) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as an output, initial value 0 */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line18, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    while (keep_running) {
        int vals[3] = {0, 0, 0};
        int written = 0;

        if (gpiod_line_set_value(line17, vals[written++]) < 0) {
            perror("gpiod_line_set_value GPIO 17");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, vals[written++]) < 0) {
            perror("gpiod_line_set_value GPIO 18");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, vals[written++]) < 0) {
            perror("gpiod_line_set_value GPIO 27");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 18: %d, GPIO 27: %d\n", vals[0], vals[1], vals[2]);
        fflush(stdout);

        usleep((useconds_t)(INTERVAL_SEC * 1000000));
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

