    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 configured as outputs (initial 0).\n");
    fflush(stdout);

    while (keep_running) {
        /* Toggle each line */
        int val2 = gpiod_line_set_value(line2, 1 - gpiod_line_get_value(line2));
        int val3 = gpiod_line_set_value(line3, 1 - gpiod_line_get_value(line3));

