            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", val2, val3);
        fflush(stdout);

        /* Sleep for 0.5 seconds, but wake early on signal */
        double remaining = POLL_INTERVAL_SEC;
        while (remaining > 0.0 && keep_running) {
            remaining = sleep(remaining);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("GPIO lines released. Exiting.\n");
    return ret;
}

