#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define TIMEOUT_US 200000
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long timeout_us) {
    long long deadline = now_us() + timeout_us;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        if (now_us() >= deadline) return -1;
    }
    return 0;
}

static float measure_distance_cm(struct gpiod_line *trigger, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: echo start timeout (device absent or not responding)\n");
        return -1.0f;
    }

    long long start = now_us();
    if (start == 0) {
        fprintf(stderr, "Error: clock_gettime failed\n");
        return -1.0f;
    }

    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: echo end timeout\n");
        return -1.0f;
    }

    long long end = now_us();
    if (end == 0) {
        fprintf(stderr, "Error: clock_gettime failed\n");
        return -1.0f;
    }

    long long elapsed_us = end - start;
    float distance = (elapsed_us * SPEED_OF_SOUND_CM_PER_S) / 2000000.0f;

    if (distance < 0.0f || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance out of range: %.2f cm\n", distance);
        return -1.0f;
    }

    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: failed to request trigger line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: failed to request echo line as input: %s\n", strerror(errno));
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance_cm(trigger, echo);
        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    printf("\nExiting cleanly.\n");
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return 0;
}

