        perror("gpiod_line_request_output GPIO 3");
        goto cleanup;
    }

    while (keep_running) {
        int v2 = rand() % 2;
        int v3 = rand() % 2;

        if (!in_range(v2) || !in_range(v3)) {
            fprintf(stderr, "Invalid value generated; skipping cycle.\n");
            sleep(SLEEP_SECONDS);
            continue;
        }

        if (gpiod_line_set_value(line2, v2) < 0) {
            perror("gpiod_line_set_value GPIO 2");
            goto cleanup;
