#include <unistd.h>
#include <gpiod.h>

#define BCM_PIN_1 2
#define BCM_PIN_2 3
#define NUM_CYCLES 3

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, BCM_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (BCM_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, BCM_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (BCM_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (0) */
    if (gpiod_line_request_output(line1, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output (BCM_PIN_1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output (BCM_PIN_2)");
        goto cleanup;
    }

    for (int cycle = 1; cycle <= NUM_CYCLES && keep_running; cycle++) {
        int val1 = (cycle % 2 == 1) ? 1 : 0;
        int val2 = (cycle % 2 == 1) ? 0 : 1;

        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value (BCM_PIN_1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value (BCM_PIN_2)");
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d = %d, GPIO %d = %d\n",
               cycle, BCM_PIN_1, val1, BCM_PIN_2, val2);
        fflush(stdout);

        /* 1-second delay between cycles */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

