#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pins[NUM_PINS] = {4, 17, 22, 27};

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    /* Install SIGINT handler so Ctrl+C releases resources cleanly. */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output and set it to 0. */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output\n", pins[i]);
            goto cleanup;
        }

        values[i] = 0;
    }

    /* Report initial state. */
    printf("Initial state: ");
    for (int i = 0; i < NUM_PINS; i++) {
        printf("%u=%d", pins[i], values[i]);
        if (i < NUM_PINS - 1) {
            printf(", ");
        }
    }
    printf("\n");
    fflush(stdout);

    /* Toggle each pin once, with a 1-second pause between toggles. */
    for (int i = 0; i < NUM_PINS && keep_running; i++) {
        values[i] = !values[i];
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "Failed to set GPIO %u\n", pins[i]);
            goto cleanup;
        }

        printf("GPIO %u toggled to %d\n", pins[i], values[i]);
        fflush(stdout);

        /* Sleep 1 second, but wake early if SIGINT arrives. */
        for (int s = 0; s < 10 && keep_running; s++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually. */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

