#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define CONSUMER "gpio-output"

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Main loop: toggle GPIO 17 every second, report state */
    while (keep_running) {
        int val = gpiod_line_get_value(line17);
        if (val < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_17, strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d: %d\n", GPIO_17, val);
        fflush(stdout);

        /* Toggle GPIO 18 every second */
        static int toggle = 0;
        if (gpiod_line_set_value(line18, toggle ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to write line %d: %s\n", GPIO_18, strerror(errno));
            goto cleanup;
        }
        toggle = !toggle;

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_TIMINGS 85
#define TIMEOUT 200

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout) {
    int i = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        usleep(1);
        i++;
        if (i > timeout) return -1;
    }
    return 0;
}

static int read_dht11(struct gpiod_line *line, int *temperature, int *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int j = 0;

    if (gpiod_line_request_output(line, "dht11", 1) < 0) return -1;
    usleep(2000);
    if (gpiod_line_request_input(line, "dht11") < 0) return -1;

    if (wait_for_level(line, 0, TIMEOUT) < 0) return -1;
    if (wait_for_level(line, 1, TIMEOUT) < 0) return -1;

    for (int i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpiod_line_get_value(line) == laststate) {
            if (!running) return -1;
            count++;
            usleep(1);
            if (count > TIMEOUT) return -1;
        }
        if (count > 0 && i >= 4 && j < 40) {
            data[j / 8] <<= 1;
            if (count > 40) data[j / 8] |= 1;
            j++;
        }
        laststate = gpiod_line_get_value(line);
    }

    if (j >= 40 && (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
        *humidity = (data[0] * 256 + data[1]);
        *temperature = (data[2] * 256 + data[3]);
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int temperature, humidity;
    if (read_dht11(line, &temperature, &humidity) == 0) {
        printf("Temperature: %d C, Humidity: %d %%\n", temperature, humidity);
        return 0;
    }

    fprintf(stderr, "Error: DHT11 not responding or data invalid.\n");
    gpiod_chip_close(chip);
    return 1;
}

