static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int check_valid(int val) {
    if (val < 0 || val > 1) {
        fprintf(stderr, "Invalid value: %d\n", val);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 2)");
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("gpiod_chip_get_line (GPIO 3)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio2_out", 0) < 0) {
