        goto cleanup;
    }

    if (gpiod_line_request_output(line3, "gpio3_out", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        int val2 = (i % 2 == 0) ? 1 : 0;
        int val3 = (i % 2 == 0) ? 0 : 1;

        if (check_valid(val2) < 0 || check_valid(val3) < 0) {
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
