            goto cleanup;
        }

        printf("Cycle %d: GPIO 2 = %d, GPIO 3 = %d\n", i + 1, val2, val3);
        fflush(stdout);

        for (int s = 0; s < CYCLE_DELAY_SEC && keep_running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
