#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define DELAY_US 150000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or no root privileges?)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM OFF\n");
        fflush(stdout);
        usleep(DELAY_US);

        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], PWM_RANGE) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM ON\n");
        fflush(stdout);
        usleep(DELAY_US);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

