    fflush(stdout);

    /* Wait for SIGINT so the line is released on exit. */
    while (g_running) {
        pause();
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
