#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line17, "gpio-output-17", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "gpio-output-18", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    /* Main loop: toggle the two lines every 0.5 seconds */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            fprintf(stderr, "Error reading GPIO values\n");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", val17, val18);
        fflush(stdout);

        /* Toggle both lines */
        if (gpiod_line_set_value(line17, val17 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, val18 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(18)");
            goto cleanup;
        }

        /* Sleep for 0.5 seconds, checking keep_running every 100 ms */
        for (int i = 0; i < 5 && keep_running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>
#include <time.h>

#define BAUD_RATE B9600
#define READ_TIMEOUT_MS 1000
#define MAX_READ_BYTES 256
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int setup_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (READ_TIMEOUT_MS + 99) / 100;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    } else if (bytes_read == 0) {
        return 0;
    } else {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        perror("read");
        return -1;
    }
}

int main(void) {
    int fd = -1;
    char buffer[MAX_READ_BYTES];

    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("open /dev/ttyAMA0");
        return EXIT_FAILURE;
    }

    if (setup_uart(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("UART initialized on /dev/ttyAMA0 at 9600 baud.\n");
    fflush(stdout);

    while (g_running) {
        int bytes_read = read_uart_data(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read == 0) {
            usleep(POLL_INTERVAL_US);
        } else {
            fprintf(stderr, "Error reading from UART.\n");
            break;
        }
    }

    if (fd != -1) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }

    printf("\nUART communication stopped.\n");
    return EXIT_SUCCESS;
}

