#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE  "w1_slave"
#define GPIO4_DEV      "4"
#define GPIO17_DEV     "17"
#define GPIO18_DEV     "18"
#define POLL_INTERVAL  5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temp(const char *device_id, float *temperature) {
    char path[256];
    char line1[256];
    char line2[256];
    int fd;
    ssize_t n;

    snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    n = read(fd, line1, sizeof(line1) - 1);
    if (n < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    line1[n] = '\0';

    n = read(fd, line2, sizeof(line2) - 1);
    if (n < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    line2[n] = '\0';

    close(fd);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Temperature conversion failed for %s\n", device_id);
        return -1;
    }

    char *t = strstr(line2, "t=");
    if (t == NULL) {
        fprintf(stderr, "Temperature data not found for %s\n", device_id);
        return -1;
    }

    long val = strtol(t + 2, NULL, 10);
    *temperature = (float)val / 1000.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    printf("Starting DS18B20 temperature readings on GPIO4, GPIO17, GPIO18...\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float t4 = 0.0f, t17 = 0.0f, t18 = 0.0f;
        int ok4 = 0, ok17 = 0, ok18 = 0;

        if (read_temp(GPIO4_DEV, &t4) == 0) { ok4 = 1; }
        if (read_temp(GPIO17_DEV, &t17) == 0) { ok17 = 1; }
        if (read_temp(GPIO18_DEV, &t18) == 0) { ok18 = 1; }

        if (ok4) printf("GPIO4: %.2f C\n", t4);
        if (ok17) printf("GPIO17: %.2f C\n", t17);
        if (ok18) printf("GPIO18: %.2f C\n", t18);

        if (!ok4 && !ok17 && !ok18) {
            fprintf(stderr, "No valid temperature readings from any sensor.\n");
        }

        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define HTU21D_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_CMD 0xE3
#define CONV_TIME_US 20000
#define POLL_INTERVAL_S 60

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_htu21d(int fd, float *temperature, float *humidity) {
    uint8_t buf[3];

    if (i2c_write_byte(fd, MEASURE_CMD) < 0) {
        return -1;
    }

    usleep(CONV_TIME_US);

    if (i2c_read_bytes(fd, buf, 3) < 0) {
        return -1;
    }

    uint16_t raw_humidity = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temp = ((uint16_t)buf[2] << 8) | buf[3];

    *humidity = -6.0f + 125.0f * ((float)raw_humidity / 65536.0f);
    *temperature = -46.85f + 175.72f * ((float)raw_temp / 65536.0f);

    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f\n", *humidity);
        return -1;
    }
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f\n", *temperature);
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("HTU21D sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_htu21d(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

