    if (gpiod_line_request_output(line3, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_3)");
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 initialized as outputs (initial LOW).\n");
    fflush(stdout);

    /* Main loop: toggle state every 2 seconds */
    int state = 0;
    while (keep_running) {
        int val2 = state ? 1 : 0;
        int val3 = state ? 0 : 1;

        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value(GPIO_2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, val3) < 0) {
            perror("gpiod_line_set_value(GPIO_3)");
            goto cleanup;
        }

        printf("GPIO 2 = %d, GPIO 3 = %d\n", val2, val3);
        fflush(stdout);

        state = !state;

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_DEVID 0xE5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Error reading DEVID: %s\n", strerror(errno));
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adxl345(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, 6) < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

int main(void) {
    int fd = -1;
    int16_t x, y, z;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    if (adxl345_init(fd) < 0) {
        close(fd);
        return 1;
    }

    while (running) {
        if (read_adxl345(fd, &x, &y, &z) == 0) {
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
            fflush(stdout);
        }
        usleep(100000);
    }

    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Warning: failed to power down ADXL345: %s\n", strerror(errno));
    }
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define NUM_CYCLES 50
#define DELAY_SEC 0.1

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Starting %d cycles on GPIO %d (BCM)\n", NUM_CYCLES, GPIO_LINE);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value HIGH");
            goto cleanup;
        }
        printf("Cycle %d: HIGH\n", i + 1);
        sleep(0);
        usleep(DELAY_SEC * 1000000);

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value LOW");
            goto cleanup;
        }
        printf("Cycle %d: LOW\n", i + 1);
        sleep(0);
        usleep(DELAY_SEC * 1000000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

