#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 17
#define DHT22_PIN2 22
#define DHT22_PIN3 23
#define DHT22_PIN4 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line1, struct gpiod_line *line2,
                      struct gpiod_line *line3, struct gpiod_line *line4,
                      float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int j = 0, counter = 0;

    if (gpiod_line_request_output(line1, "dht22", 1) < 0) return -1;
    if (gpiod_line_request_input(line2, "dht22") < 0) return -1;
    if (gpiod_line_request_input(line3, "dht22") < 0) return -1;
    if (gpiod_line_request_input(line4, "dht22") < 0) return -1;

    usleep(1000000);

    gpiod_line_set_value(line1, 0);
    usleep(20000);
    gpiod_line_set_value(line1, 1);
    usleep(30);

    for (int i = 0; i < 85; i++) {
        counter = 0;
        while (gpiod_line_get_value(line2) == laststate) {
            counter++;
            usleep(1);
            if (counter == 255) return -1;
        }
        laststate = gpiod_line_get_value(line2);

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (j < 40) return -1;

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *hum = (float)((data[0] << 8) + data[1]) / 10.0;
    *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL, *line4 = NULL;
    float temp = 0.0, hum = 0.0;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN2);
    line3 = gpiod_chip_get_line(chip, DHT22_PIN3);
    line4 = gpiod_chip_get_line(chip, DHT22_PIN4);
    if (!line1 || !line2 || !line3 || !line4) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    while (running) {
        int ret = read_dht22(line1, line2, line3, line4, &temp, &hum);
        if (ret == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Error reading DHT22 sensor\n");
        }
        sleep(2);
    }

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line4) gpiod_line_release(line4);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_1 500
#define PWM_DUTY_2 700
#define PWM_DUTY_3 300
#define INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or no permission)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, PWM_DUTY_1) != 0 ||
            gpioPWM(PWM_PIN_2, PWM_DUTY_2) != 0 ||
            gpioPWM(PWM_PIN_3, PWM_DUTY_3) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM17=%d PWM22=%d PWM27=%d\n", PWM_DUTY_1, PWM_DUTY_2, PWM_DUTY_3);
        fflush(stdout);
        gpioDelay(INTERVAL_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

