#define CONSUMER "gpio-output"
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define INTERVAL_SEC 0.2

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int gpios[4] = {GPIO_17, GPIO_22, GPIO_23, GPIO_24};
    int values[4] = {0, 1, 0, 1};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
