#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)
#define CAPTURE_TIMEOUT_MS 1000

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    void *buffer = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Device did not accept requested format (w=%d h=%d)\n",
                IMAGE_WIDTH, IMAGE_HEIGHT);
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = CAPTURE_TIMEOUT_MS / 1000;
    tv.tv_usec = (CAPTURE_TIMEOUT_MS % 1000) * 1000;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "select interrupted by signal\n");
        } else {
            fprintf(stderr, "select failed: %s\n", strerror(errno));
        }
        goto cleanup;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout: device did not return a frame\n");
        goto cleanup;
    }

    if (g_stop) {
        fprintf(stderr, "Interrupted before capture\n");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen("image.yuyv", "wb");
    if (!fp) {
        fprintf(stderr, "Error opening image file: %s\n", strerror(errno));
        goto cleanup;
    }

    size_t written = fwrite(buffer, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Short write: %zu of %u bytes\n", written, buf.bytesused);
        goto cleanup;
    }

    printf("Image captured and saved to image.yuyv\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, buf.length);
    }
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_22 22
#define GPIO_27 27
#define POLL_INTERVAL_SEC 0.01

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line22 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line22) {
        perror("gpiod_chip_get_line(22)");
        goto cleanup;
    }
    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line22, "gpio-output-22", 0) < 0) {
        perror("gpiod_line_request_output(22)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line27, "gpio-output-27", 0) < 0) {
        perror("gpiod_line_request_output(27)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 10 ms */
    while (keep_running) {
        int val22 = gpiod_line_get_value(line22);
        int val27 = gpiod_line_get_value(line27);
        if (val22 < 0 || val27 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("GPIO 22: %d, GPIO 27: %d\n", val22, val27);
        fflush(stdout);

        /* Toggle both lines */
        if (gpiod_line_set_value(line22, val22 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(22)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, val27 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(27)");
            goto cleanup;
        }

        usleep((useconds_t)(POLL_INTERVAL_SEC * 1000000));
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line22) gpiod_line_release(line22);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ssd1306_command(int fd, uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    return i2c_write(fd, buf, 2);
}

static int ssd1306_init(int fd) {
    uint8_t init_cmds[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40,
        0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12,
        0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6,
        0xAF
    };
    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        if (ssd1306_command(fd, init_cmds[i]) < 0) return -1;
    }
    return 0;
}

static int ssd1306_clear(int fd) {
    uint8_t buf[SSD1306_WIDTH + 1];
    buf[0] = 0x40;
    memset(&buf[1], 0, SSD1306_WIDTH);
    for (int page = 0; page < SSD1306_PAGES; page++) {
        if (ssd1306_command(fd, 0xB0 + page) < 0) return -1;
        if (ssd1306_command(fd, 0x00) < 0) return -1;
        if (ssd1306_command(fd, 0x10) < 0) return -1;
        if (i2c_write(fd, buf, sizeof(buf)) < 0) return -1;
    }
    return 0;
}

static int ssd1306_display_string(int fd, int page, const char *str) {
    uint8_t buf[SSD1306_WIDTH + 1];
    buf[0] = 0x40;
    memset(&buf[1], 0, SSD1306_WIDTH);
    int len = (int)strlen(str);
    for (int i = 0; i < len; i++) {
        buf[1 + i] = (uint8_t)str[i];
    }
    if (ssd1306_command(fd, 0xB0 + page) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x10) < 0) return -1;
    if (i2c_write(fd, buf, sizeof(buf)) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SSD1306_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed.\n");
        close(fd);
        return 1;
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        if (ssd1306_display_string(fd, 0, "Hello, World!") < 0) {
            fprintf(stderr, "Display write failed.\n");
            break;
        }
        usleep(100000);
    }

    ssd1306_clear(fd);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
