#define CONSUMER "gpio-test"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5
#define INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int offsets[3] = {GPIO_2, GPIO_3, GPIO_5};
    int values[3] = {0, 0, 0};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", offsets[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", offsets[i]);
            goto cleanup;
        }
    }

    while (keep_running) {
        for (int i = 0; i < 3; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO %d\n", offsets[i]);
                goto cleanup;
            }
        }
        printf("GPIO 2: %d, GPIO 3: %d, GPIO 5: %d\n", values[0], values[1], values[2]);
        fflush(stdout);
        sleep(INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM ON\n");
        fflush(stdout);
        sleep(1);

        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM OFF\n");
        fflush(stdout);
        sleep(1);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define LED_PIN     24

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000
#define LOOP_DELAY_US     200000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    struct gpiod_line *led  = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led  = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hcsr04-led", 0) < 0) {
        perror("gpiod_line_request_output (led)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Ensure trigger is low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trig low)");
            break;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value (trig high)");
            break;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trig low)");
            break;
        }

        /* Wait for echo rising edge (timeout) */
        long long t0 = now_us();
        if (t0 < 0) break;
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                break;
            }
            if (now_us() - t0 > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo start timeout (no echo)\n");
                break;
            }
        } while (val == 0);
        if (val < 0) break;
        if (!running) break;

        /* Measure echo high duration */
        long long start = now_us();
        if (start < 0) break;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                break;
            }
            if (now_us() - start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo end timeout (no echo)\n");
                break;
            }
        } while (val == 1);
        if (val < 0) break;
        if (!running) break;

        long long end = now_us();
        if (end < 0) break;

        long long duration = end - start;
        double distance = (duration / 1000000.0) * 34300.0 / 2.0;

        int led_state = (distance > 0.0 && distance < 400.0) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            perror("gpiod_line_set_value (led)");
            break;
        }

        printf("Distance: %.2f cm, LED: %s\n", distance, led_state ? "ON" : "OFF");
        fflush(stdout);

        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (led)  gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nClean exit.\n");

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define NUM_PIXELS 10
#define DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int i;
    int red, green, blue;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (i = 0; i < NUM_PIXELS; i++) {
            red   = (i % 2 == 0) ? 255 : 0;
            green = (i % 3 == 0) ? 255 : 0;
            blue  = (i % 5 == 0) ? 255 : 0;

            if (gpioWrite(GPIO_PIN, red) != 0) {
                fprintf(stderr, "Failed to write red to GPIO %d\n", GPIO_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            usleep(DELAY_US);

            if (gpioWrite(GPIO_PIN, green) != 0) {
                fprintf(stderr, "Failed to write green to GPIO %d\n", GPIO_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            usleep(DELAY_US);

            if (gpioWrite(GPIO_PIN, blue) != 0) {
                fprintf(stderr, "Failed to write blue to GPIO %d\n", GPIO_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            usleep(DELAY_US);
        }
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

