    uint8_t chip_id;
    if (bme280_read_id(fd, &chip_id) != 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x60)\n", chip_id);
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_RESET, 0xB6) != 0) {
        fprintf(stderr, "Error: Failed to reset BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set humidity oversampling: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) != 0) {
        fprintf(stderr, "Error: Failed to set config register: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to set ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

