#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define LCD_ADDR 0x27

#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

#define LCD_WIDTH 16

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char val) {
    if (write(fd, &val, 1) != 1) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int lcd_strobe(int fd, unsigned char data) {
    if (i2c_write_byte(fd, data | ENABLE | LCD_BACKLIGHT) < 0) return -1;
    usleep(1);
    if (i2c_write_byte(fd, data & ~ENABLE | LCD_BACKLIGHT) < 0) return -1;
    usleep(50);
    return 0;
}

static int lcd_byte(int fd, unsigned char bits, int mode) {
    unsigned char bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    unsigned char bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    if (i2c_write_byte(fd, bits_high) < 0) return -1;
    if (lcd_strobe(fd, bits_high) < 0) return -1;
    if (i2c_write_byte(fd, bits_low) < 0) return -1;
    if (lcd_strobe(fd, bits_low) < 0) return -1;
    return 0;
}

static int lcd_init(int fd) {
    usleep(50000);
    if (lcd_byte(fd, 0x33, LCD_CMD) < 0) return -1;
    if (lcd_byte(fd, 0x32, LCD_CMD) < 0) return -1;
    if (lcd_byte(fd, 0x28, LCD_CMD) < 0) return -1;
    if (lcd_byte(fd, 0x0C, LCD_CMD) < 0) return -1;
    if (lcd_byte(fd, 0x06, LCD_CMD) < 0) return -1;
    if (lcd_byte(fd, 0x01, LCD_CMD) < 0) return -1;
    usleep(2000);
    return 0;
}

static int lcd_clear(int fd) {
    if (lcd_byte(fd, 0x01, LCD_CMD) < 0) return -1;
    usleep(2000);
    return 0;
}

static int lcd_set_cursor(int fd, int col, int row) {
    unsigned char row_offsets[] = {0x00, 0x40, 0x14, 0x54};
    if (row < 0 || row > 3 || col < 0 || col > 15) return -1;
    return lcd_byte(fd, (row + row_offsets[row]) + col, LCD_CMD);
}

static int lcd_print(int fd, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        if (lcd_byte(fd, text[i], LCD_CHR) < 0) return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    char buffer[LCD_WIDTH + 1];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    if (lcd_init(fd) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (lcd_clear(fd) < 0) {
            fprintf(stderr, "Failed to clear display\n");
            break;
        }
        if (lcd_set_cursor(fd, 0, 0) < 0) {
            fprintf(stderr, "Failed to set cursor\n");
            break;
        }
        if (lcd_print(fd, buffer) < 0) {
            fprintf(stderr, "Failed to print to display\n");
            break;
        }

        sleep(10);
    }

    lcd_clear(fd);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 not detected at address 0x%02X\n", MPU6050_ADDR);
        goto cleanup;
    }

    printf("MPU6050 initialized at address 0x%02X\n", MPU6050_ADDR);

    for (int i = 0; i < 100 && g_running; i++) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            goto cleanup;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Reading %d: X=%d, Y=%d, Z=%d\n", i + 1, accel_x, accel_y, accel_z);
        fflush(stdout);
        usleep(100000);
    }

    if (!g_running) {
        fprintf(stderr, "\nInterrupt received, exiting early.\n");
    } else {
        printf("100 readings completed.\n");
        ret = EXIT_SUCCESS;
    }

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_14 14
#define GPIO_15 15
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (line14 == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_14, strerror(errno));
        goto cleanup;
    }
    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (line15 == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_15, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line14, "gpio-output-14", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_14, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line15, "gpio-output-15", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_15, strerror(errno));
        goto cleanup;
    }

    printf("GPIO 14 and 15 configured as outputs (initial 0). Polling every %d s.\n",
           POLL_INTERVAL_SEC);
    fflush(stdout);

    while (keep_running) {
        /* Toggle: 0 -> 1 -> 0 */
        int val14 = 0;
        int val15 = 1;

        if (gpiod_line_set_value(line14, val14) < 0) {
            fprintf(stderr, "Failed to set line %d: %s\n", GPIO_14, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line15, val15) < 0) {
            fprintf(stderr, "Failed to set line %d: %s\n", GPIO_15, strerror(errno));
            goto cleanup;
        }

        printf("GPIO 14 = %d, GPIO 15 = %d\n", val14, val15);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line14 != NULL) {
        gpiod_line_release(line14);
    }
    if (line15 != NULL) {
        gpiod_line_release(line15);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Clean shutdown.\n");
    }
    return ret;
}

#include <stdio.h>
