#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "raspberry_pi_sensor"
#define MQTT_QOS 1

#define SENSOR_READING_INTERVAL_MS 100
#define MAX_RETRIES 5

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17

static volatile sig_atomic_t program_running = 1;
static pthread_mutex_t sensor_mutex = PTHREAD_MUTEX_INITIALIZER;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_sensor_data(int *sensor_value) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    *sensor_value = value;
    return 0;
}

static bool validate_sensor_data(int sensor_value) {
    return (sensor_value == 0 || sensor_value == 1);
}

static void publish_sensor_data(int sensor_value) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    pubmsg.payload = (void *)(char *){"sensor_value: 12345"};
    pubmsg.payloadlen = strlen((char *)pubmsg.payload);
    pubmsg.payloadtype = MQTTClient_byte;
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
    } else {
        printf("Message published to topic %s\n", MQTT_TOPIC);
    }
}

int main() {
    int rc;
    int sensor_value;
    int retries = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    rc = gpiod_line_request_input(line, "sensor_reader");
    if (rc < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient client;
    if ((rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Connected to MQTT broker. Publishing sensor data...\n");

    while (program_running) {
        if (read_sensor_data(&sensor_value) != 0) {
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            usleep(100000);
            continue;
        }

        if (validate_sensor_data(sensor_value)) {
            pthread_mutex_lock(&sensor_mutex);
            publish_sensor_data(sensor_value);
            pthread_mutex_unlock(&sensor_mutex);
            retries = 0;
        } else {
            fprintf(stderr, "Invalid sensor data: %d\n", sensor_value);
        }

        usleep(SENSOR_READING_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d initialized as output (initial state: 0)\n", GPIO_LINE);
    fflush(stdout);

    /* Main loop: toggle every 5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO %d state: %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Toggle the value */
        val = val ? 0 : 1;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        /* Sleep for the interval, checking keep_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define LED_PIN     27

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0
#define TIMEOUT_US 20000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long timeout_us) {
    long long deadline = now_us() + timeout_us;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        if (now_us() >= deadline) return -1;
        usleep(100);
    }
    return 0;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1.0;
    usleep(2);

    if (gpiod_line_set_value(trig, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1.0;

    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) return -1.0;
    long long start = now_us();
    if (start == 0) return -1.0;

    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) return -1.0;
    long long end = now_us();

    float pulse_us = (float)(end - start);
    float distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) return -1.0;
    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *led  = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        fprintf(stderr, "Failed to acquire GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hcsr04-led", 0) < 0) {
        perror("gpiod_line_request_output led");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance < 0.0) {
            printf("Error: measurement failed or out of range.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("gpiod_line_set_value led on");
            }
            usleep(500000);
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value led off");
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting cleanly.\n");
    gpiod_line_set_value(led, 0);

cleanup:
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

