#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio-test"
#define GPIO_2  2
#define GPIO_3  3
#define GPIO_23 23
#define INTERVAL_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    int gpios[] = {GPIO_2, GPIO_3, GPIO_23};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_gpios; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", gpios[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < num_gpios; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", gpios[i]);
            goto cleanup;
        }
    }

    while (keep_running) {
        for (int i = 0; i < num_gpios; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high\n", gpios[i]);
                goto cleanup;
            }
            printf("GPIO %d set HIGH\n", gpios[i]);
            fflush(stdout);
        }
        sleep(INTERVAL_SEC);

        if (!keep_running) break;

        for (int i = 0; i < num_gpios; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low\n", gpios[i]);
                goto cleanup;
            }
            printf("GPIO %d set LOW\n", gpios[i]);
            fflush(stdout);
        }
        sleep(INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < num_gpios; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

