#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 500
#define INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or no root privileges?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d: range=%d, frequency=%d Hz, duty=%d\n",
           PWM_PIN, PWM_RANGE, PWM_FREQUENCY, PWM_DUTY_CYCLE);
    fflush(stdout);

    while (running) {
        sleep(INTERVAL_SEC);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define TIMEOUT_US 200000
#define POLL_INTERVAL_S 0.2

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    long long start_us, end_us, elapsed_us;

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    start_us = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (!running) return -1.0f;
        if (now_us() - start_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0f;
        }
    }
    start_us = now_us();

    while (gpiod_line_get_value(echo) == 1) {
        if (!running) return -1.0f;
        if (now_us() - start_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0f;
        }
    }
    end_us = now_us();

    elapsed_us = end_us - start_us;
    float distance = (elapsed_us * SPEED_OF_SOUND_CM_PER_S) / 2000000.0f;

    if (distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0f;
    }

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance(trigger, echo);
        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed.\n");
        }
        sleep(2);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_4, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM state: %d%%\n", duty_cycle);
        fflush(stdout);

        duty_cycle += 10;
        if (duty_cycle > PWM_RANGE) {
            duty_cycle = 0;
        }

        time_sleep(0.1);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

