static int read_sensor(int pin, int min_val, int max_val, int *out) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (val < min_val || val > max_val) {
        fprintf(stderr, "Invalid reading on GPIO %d: %d (expected %d-%d)\n",
                pin, val, min_val, max_val);
        return -1;
    }
    *out = val;
    return 0;
}

