    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    while (running) {
        bool read_ok = false;

        for (attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_sensor(SENSOR1_PIN, SENSOR1_MIN, SENSOR1_MAX, &sensor1_val) == 0 &&
                read_sensor(SENSOR2_PIN, SENSOR2_MIN, SENSOR2_MAX, &sensor2_val) == 0) {
                read_ok = true;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(100000);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", MAX_RETRIES);
            break;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        snprintf(payload, sizeof(payload), "%s, Sensor1: %d, Sensor2: %d",
                 timestamp, sensor1_val, sensor2_val);

        if (publish_mqtt(payload) != 0) {
            fprintf(stderr, "Failed to publish MQTT message.\n");
            break;
        }

        printf("Published: %s\n", payload);

        if (running) {
            gpioDelay(SENSOR_READ_INTERVAL_MS * 1000);
        }
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "raspberry_pi_sensor"
#define MQTT_QOS 1
#define NUM_READINGS 10
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_ads1115(int handle, int16_t *reading) {
    uint16_t config = 0x8000 | (0x4000) | (0x0000) | (0x0000) | (0x0000) | (0x0000) | (0x0000);
    if (i2c_write_reg(handle, ADS1115_REG_CONFIG, config) != 0) return -1;
    gpioDelay(10000);
    uint16_t val;
    if (i2c_read_reg(handle, ADS1115_REG_CONVERSION, &val) != 0) return -1;
    *reading = (int16_t)val;
    return 0;
}

static int publish_mqtt_message(const char *message) {
    int rc = MQTT_SUCCESS;
    int msg_id = mosquitto_publish(NULL, NULL, MQTT_TOPIC, strlen(message), message, MQTT_QOS, false);
    if (msg_id == MQTT_SUCCESS) {
        while (mosquitto_loop_wait(NULL) == MQTT_SUCCESS) {
            if (mosquitto_loop_check_msg_id(msg_id) == MQTT_SUCCESS) {
                rc = mosquitto_loop_check_msg_id(msg_id);
                break;
            }
        }
    }
    return rc;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, ADS1115_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int rc = MQTT_SUCCESS;
    mosquitto_lib_init();
    mosquitto_message_callback_set(NULL, NULL);
    mosquitto_connect_callback_set(NULL, NULL);
    mosquitto_disconnect_callback_set(NULL, NULL);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        int16_t reading;
        if (read_ads1115(i2c_handle, &reading) != 0) {
            fprintf(stderr, "Failed to read ADS1115: %s\n", strerror(errno));
            rc = 1;
            break;
        }
        char message[64];
        snprintf(message, sizeof(message), "Reading %d: %d", i + 1, reading);
        rc = publish_mqtt_message(message);
        if (rc != MQTT_SUCCESS) {
            fprintf(stderr, "Failed to publish MQTT message: %s\n", mosquitto_strerror(rc));
            break;
        }
        gpioDelay(1000000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    mosquitto_lib_cleanup();
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define POLL_INTERVAL_SEC 0.05

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (line17 == NULL) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (line18 == NULL) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line17, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    /* Main loop: toggle the two lines every 0.05 seconds */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            fprintf(stderr, "Error reading GPIO values (17=%d, 18=%d)\n", val17, val18);
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", val17, val18);
        fflush(stdout);

        /* Toggle both lines */
        if (gpiod_line_set_value(line17, val17 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, val18 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(18)");
            goto cleanup;
        }

        usleep((useconds_t)(POLL_INTERVAL_SEC * 1000000));
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17 != NULL) {
        gpiod_line_release(line17);
    }
    if (line18 != NULL) {
        gpiod_line_release(line18);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

