#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <sys/time.h>
#include <syslog.h>
#include <pthread.h>
#include <gpiod.h>

#include <MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "raspberry_pi_sensor"
#define MQTT_QOS 1

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define SENSOR_3_PIN 22

#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup_gpio(void) {
    if (line1) { gpiod_line_release(line1); line1 = NULL; }
    if (line2) { gpiod_line_release(line2); line2 = NULL; }
    if (line3) { gpiod_line_release(line3); line3 = NULL; }
    if (chip)  { gpiod_chip_close(chip); chip = NULL; }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    line3 = gpiod_chip_get_line(chip, SENSOR_3_PIN);
    if (!line1 || !line2 || !line3) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_input(line1, "sensor1") < 0 ||
        gpiod_line_request_input(line2, "sensor2") < 0 ||
        gpiod_line_request_input(line3, "sensor3") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines as input: %s", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    return 0;
}

static int read_sensor(struct gpiod_line *line, const char *name) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        syslog(LOG_ERR, "Failed to read %s: %s", name, strerror(errno));
        return -1;
    }
    return val;
}

static void publish_data(MQTTClient client, int s1, int s2, int s3) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char payload[256];
    int len = snprintf(payload, sizeof(payload),
        "{\"timestamp\":\"%s\",\"sensor1\":%d,\"sensor2\":%d,\"sensor3\":%d}",
        timestamp, s1, s2, s3);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "Payload formatting failed");
        return;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)len;
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", MQTTClient_strerror(rc));
    } else {
        syslog(LOG_INFO, "Published: %s", payload);
    }
}

int main(void) {
    openlog("sensor_app", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (init_gpio() != 0) {
        closelog();
        return 1;
    }

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID,
        MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", MQTTClient_strerror(rc));
        cleanup_gpio();
        closelog();
        return 1;
    }

    rc = MQTTClient_setCallbacks(client, NULL, NULL, NULL, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to set callbacks: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        cleanup_gpio();
        closelog();
        return 1;
    }

    rc = MQTTClient_connect(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        cleanup_gpio();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker. Publishing sensor data...");

    while (running) {
        int s1 = read_sensor(line1, "sensor1");
        int s2 = read_sensor(line2, "sensor2");
        int s3 = read_sensor(line3, "sensor3");

        if (s1 >= 0 && s2 >= 0 && s3 >= 0) {
            publish_data(client, s1, s2, s3);
        }

        struct timespec ts = {0, SAMPLE_INTERVAL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    syslog(LOG_INFO, "Shutting down...");
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    cleanup_gpio();
    closelog();
    return 0;
}

