        return EXIT_FAILURE;
    }

    int duty1 = 0, duty2 = 0, duty3 = 0;
    int step = 1;

    while (running) {
        gpioPWM(PWM_PIN_1, duty1);
        gpioPWM(PWM_PIN_2, duty2);
        gpioPWM(PWM_PIN_3, duty3);

        printf("PWM17=%d PWM22=%d PWM27=%d\n", duty1, duty2, duty3);
        fflush(stdout);

        duty1 += step;
        duty2 += step;
        duty3 += step;

        if (duty1 >= PWM_RANGE) {
            duty1 = PWM_RANGE - 1;
            step = -1;
        } else if (duty1 <= 0) {
            duty1 = 0;
            step = 1;
        }

        if (duty2 >= PWM_RANGE) {
            duty2 = PWM_RANGE - 1;
            step = -1;
        } else if (duty2 <= 0) {
            duty2 = 0;
            step = 1;
        }

        if (duty3 >= PWM_RANGE) {
            duty3 = PWM_RANGE - 1;
            step = -1;
        } else if (duty3 <= 0) {
            duty3 = 0;
            step = 1;
        }

        usleep(DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)
#define CAPTURE_INTERVAL 1

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    void *buffer = NULL;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer, IMAGE_SIZE);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer, IMAGE_SIZE);
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            break;
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "image_%ld.jpg", (long)time(NULL));
        FILE *fp = fopen(filename, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
            xioctl(fd, VIDIOC_STREAMOFF, &type);
            munmap(buffer, IMAGE_SIZE);
            close(fd);
            return EXIT_FAILURE;
        }

        size_t bytes_written = fwrite(buffer, 1, buf.bytesused, fp);
        if (bytes_written != buf.bytesused) {
            fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
            fclose(fp);
            xioctl(fd, VIDIOC_STREAMOFF, &type);
            munmap(buffer, IMAGE_SIZE);
            close(fd);
            return EXIT_FAILURE;
        }

        if (fclose(fp) == EOF) {
            fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            break;
        }

        sleep(CAPTURE_INTERVAL);
    }

    xioctl(fd, VIDIOC_STREAMOFF, &type);
    munmap(buffer, IMAGE_SIZE);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void)
{
    const char *dev_name = "/dev/video0";
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer_start = NULL;
    size_t buffer_length = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    CLEAR(sa);
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Cannot open '%s': %s\n", dev_name, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        if (errno == ENODEV) {
            fprintf(stderr, "Device '%s' not found (no camera module or device missing)\n", dev_name);
        } else {
            fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        }
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device '%s' does not support video capture\n", dev_name);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device '%s' does not support streaming I/O\n", dev_name);
        goto cleanup;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer_length = buf.length;
    buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        buffer_start = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "select interrupted by signal\n");
        } else {
            fprintf(stderr, "select failed: %s\n", strerror(errno));
        }
        goto cleanup;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout: camera did not return a frame\n");
        goto cleanup;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    FILE *out = fopen("image.yuyv", "wb");
    if (!out) {
        fprintf(stderr, "Cannot open image.yuyv for writing: %s\n", strerror(errno));
        goto cleanup;
    }

    size_t written = fwrite(buffer_start, 1, buffer_length, out);
    if (written != buffer_length) {
        fprintf(stderr, "Short write: %zu of %zu bytes\n", written, buffer_length);
        fclose(out);
        goto cleanup;
    }

    if (fclose(out) != 0) {
        fprintf(stderr, "Error closing image file: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Image saved as image.yuyv (%zu bytes)\n", buffer_length);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
    }
    if (buffer_start && buffer_start != MAP_FAILED) {
        munmap(buffer_start, buffer_length);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_2)");
        goto cleanup;
    }
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("gpiod_chip_get_line(GPIO_3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_3)");
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 configured as outputs (initial 0).\n");
    fflush(stdout);

    /* Main loop: toggle both lines every 0.5 seconds */
    while (keep_running) {
        int val2 = gpiod_line_get_value(line2);
        int val3 = gpiod_line_get_value(line3);

        if (val2 < 0 || val3 < 0) {
            fprintf(stderr, "Error reading GPIO values.\n");
            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", val2, val3);
        fflush(stdout);

        /* Toggle both lines */
        if (gpiod_line_set_value(line2, val2 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(GPIO_2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, val3 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(GPIO_3)");
            goto cleanup;
        }

        /* Sleep for 0.5 seconds, checking keep_running every 100 ms */
        for (int i = 0; i < 5 && keep_running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("GPIO lines released. Exiting.\n");
    }
    return ret;
}

