#define MAX_RETRIES 3
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART device");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = IGNPAR;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);

    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (READ_TIMEOUT_MS + 999) / 1000;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    if (tcflush(fd, TCIOFLUSH) != 0) {
        perror("Warning: tcflush failed");
    }

    return fd;
}

static int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        perror("Error reading from UART");
        return -1;
    }
    if (bytes_read == 0) {
        return 0;
    }

    buffer[bytes_read] = '\0';
    return (int)bytes_read;
}

int main(void) {
    const char *device = "/dev/ttyAMA0";
    speed_t baud_rate = BAUD_RATE;

    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    int fd = setup_uart(device, baud_rate);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[DATA_SIZE];
    int bytes_read;

    while (keep_running) {
        bytes_read = read_uart_data(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            break;
        }
        usleep(100000);
    }

    if (close(fd) == -1) {
        perror("Error closing UART device");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24
#define CONSUMER "gpio-output"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int values[3] = {0, 0, 0};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_18);
    lines[1] = gpiod_chip_get_line(chip, GPIO_23);
    lines[2] = gpiod_chip_get_line(chip, GPIO_24);
    if (!lines[0] || !lines[1] || !lines[2]) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(lines[0], CONSUMER, 0) < 0 ||
        gpiod_line_request_output(lines[1], CONSUMER, 0) < 0 ||
        gpiod_line_request_output(lines[2], CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", i + GPIO_18, strerror(errno));
            goto cleanup;
        }
        values[i] = 1;
    }

    printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
           GPIO_18, values[0],
           GPIO_23, values[1],
           GPIO_24, values[2]);
    fflush(stdout);

    while (g_running) {
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 500;
    if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on GPIO %d (range=%d, frequency=%d Hz, duty=%d/1000)\n",
           PWM_PIN, PWM_RANGE, PWM_FREQUENCY, duty_cycle);
    fflush(stdout);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped on GPIO %d\n", PWM_PIN);
    fflush(stdout);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio-output-demo", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d initialized as output (initial state: LOW)\n", GPIO_LINE);
    fflush(stdout);

    /* Main loop: toggle every 2 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO %d state: %s\n", GPIO_LINE, val ? "HIGH" : "LOW");
        fflush(stdout);

        /* Toggle the output */
        if (gpiod_line_set_value(line, val ? 0 : 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        /* Sleep for 2 seconds, checking keep_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

