#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or no root privileges?)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM applied: GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               PWM_PIN_1, duty_cycle,
               PWM_PIN_2, duty_cycle,
               PWM_PIN_3, duty_cycle);
        fflush(stdout);

        duty_cycle = (duty_cycle + 10) % PWM_RANGE;
        if (duty_cycle == 0) duty_cycle = 1;

        gpioDelay(DELAY_US);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85
#define TIMEOUT 200

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout) {
    int i = 0;
    while (gpiod_line_get_value(line) != level) {
        if (i++ > timeout) return -1;
        usleep(1);
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int j = 0, counter = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    usleep(500000);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, TIMEOUT) < 0) return -1;
    if (wait_for_level(line, 1, TIMEOUT) < 0) return -1;

    for (int i = 0; i < MAX_TIMINGS && running; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate && running) {
            counter++;
            usleep(1);
            if (counter == 255) return -1;
        }
        laststate = gpiod_line_get_value(line);

        if ((i > 3 && i % 2 == 0) && (data[j / 8] <<= 1)) {
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (!running) return -1;

    if (j >= 40) {
        data[0] = ((data[0] & 0x07FF) | (data[0] << 8)) >> 8;
        data[1] = ((data[1] & 0x01F) | (data[1] << 6)) >> 6;
        data[2] = ((data[2] & 0x03F) | (data[2] << 4)) >> 4;
        data[3] = ((data[3] & 0x07F) | (data[3] << 2)) >> 2;
        data[4] = ((data[4] & 0x0FF) | (data[4] << 8)) >> 8;

        if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) == data[4]) {
            *humidity = (float)((data[0] * 256) + data[1]) / 10.0;
            *temperature = (float)((data[2] & 0x7F) * 256 + data[3]) / 10.0;
            if (data[2] & 0x80) *temperature = -*temperature;
            return 0;
        }
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float temperature, humidity;
    if (read_dht22(line, &temperature, &humidity) == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Error reading DHT22 sensor.\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

