#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MCP3008_CHANNEL 0
#define MCP3008_VREF 3.3f
#define MCP3008_RESOLUTION 1024.0f
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    int handle = i2cOpen(1, 0, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    int result = i2cWriteDevice(handle, tx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(handle);
        return -1;
    }

    result = i2cReadDevice(handle, rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        i2cClose(handle);
        return -1;
    }

    i2cClose(handle);

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return (adc_value / MCP3008_RESOLUTION) * MCP3008_VREF;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, 0, 0);
    if (handle < 0) {
