    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO 17)");
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line (GPIO 18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (0) */
    if (gpiod_line_request_output(line17, "gpio-cycles", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "gpio-cycles", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 18)");
        goto cleanup;
    }

    /* Main loop: complete 3 cycles, checking for signal each iteration */
    for (int cycle = 1; cycle <= NUM_CYCLES && keep_running; cycle++) {
        /* Cycle 1: GPIO 17 HIGH, GPIO 18 LOW */
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 17 HIGH)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 18 LOW)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 HIGH, GPIO 18 LOW\n", cycle);
        fflush(stdout);
        usleep(500000); /* 500 ms */

        /* Cycle 2: GPIO 17 LOW, GPIO 18 HIGH */
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 17 LOW)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 18 HIGH)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 LOW, GPIO 18 HIGH\n", cycle);
        fflush(stdout);
        usleep(500000);

        /* Cycle 3: GPIO 17 HIGH, GPIO 18 HIGH */
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 17 HIGH)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 18 HIGH)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 HIGH, GPIO 18 HIGH\n", cycle);
        fflush(stdout);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    if (keep_running == 0) {
        printf("\nInterrupt received, exiting gracefully.\n");
