static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int display_clear(int fd) {
    return i2c_write_byte(fd, 0x00);
}

static int display_set_cursor(int fd, uint8_t row, uint8_t col) {
    if (row > DISPLAY_HEIGHT || col > DISPLAY_WIDTH) {
        fprintf(stderr, "Invalid cursor position: row=%u, col=%u\n", row, col);
        return -1;
    }
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    return i2c_write_byte(fd, addr);
}

static int display_write_string(int fd, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        if (i > 19) break;
        if (i2c_write_byte(fd, (uint8_t)str[i]) != 0) {
            return -1;
        }
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("PCF8574 Display Program (I2C address 0x%02X)\n", PCF8574_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (display_clear(fd) != 0) {
            fprintf(stderr, "Failed to clear display\n");
            break;
        }

        if (display_set_cursor(fd, 0, 0) != 0) {
            fprintf(stderr, "Failed to set cursor position\n");
            break;
        }

        char message[DISPLAY_WIDTH + 1];
        snprintf(message, sizeof(message), "Hello, World!");

        if (display_write_string(fd, message) != 0) {
            fprintf(stderr, "Failed to write to display\n");
            break;
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

