#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_1 500
#define PWM_DUTY_2 700
#define PWM_DUTY_3 300
#define DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or no root privileges?)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, PWM_DUTY_1) != 0 ||
            gpioPWM(PWM_PIN_2, PWM_DUTY_2) != 0 ||
            gpioPWM(PWM_PIN_3, PWM_DUTY_3) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM1=%d PWM2=%d PWM3=%d\n", PWM_DUTY_1, PWM_DUTY_2, PWM_DUTY_3);
        fflush(stdout);
        usleep(DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define TIMEOUT_US 30000
#define CONSUMER "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(50);

    /* Send 10us trigger pulse */
    if (gpiod_line_set_value(trig_line, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Wait for echo to go high (with timeout) */
    long long start_wait = now_us();
    int val;
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
            goto cleanup;
        }
        if (!running) break;
    } while (val == 0);
    if (!running) {
        fprintf(stderr, "Interrupted before echo high\n");
        goto cleanup;
    }
    if (val != 1) {
        fprintf(stderr, "Echo never went high (device absent or not responding)\n");
        goto cleanup;
    }
    long long echo_start = now_us();

    /* Wait for echo to go low (with timeout) */
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
            goto cleanup;
        }
        if (!running) break;
    } while (val == 1);
    if (!running) {
        fprintf(stderr, "Interrupted before echo low\n");
        goto cleanup;
    }
    if (val != 0) {
        fprintf(stderr, "Echo never went low (device absent or not responding)\n");
        goto cleanup;
    }
    long long echo_end = now_us();

    long long pulse_us = echo_end - echo_start;
    if (pulse_us <= 0) {
        fprintf(stderr, "Invalid pulse duration: %lld us\n", pulse_us);
        goto cleanup;
    }

    double distance_cm = (double)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0;

    if (distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance_cm);
        goto cleanup;
    }

    printf("Distance: %.2f cm\n", distance_cm);
    ret = EXIT_SUCCESS;

cleanup:
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 23
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, "gpio-output-demo", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output (LOW). Polling every %d seconds.\n",
           GPIO_LINE_OFFSET, POLL_INTERVAL_SEC);
    fflush(stdout);

    while (keep_running) {
        /* Toggle the output state */
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_value = (current_value == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, new_value);
        fflush(stdout);

        /* Sleep for the poll interval, but wake early on signal */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released. Exiting.\n", GPIO_LINE_OFFSET);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define ACCEL_XOUT_H   0x3B
#define SAMPLE_PERIOD  0.1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst: read 0x%02X: got %zd of %zu (%s)\n",
                reg, n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);
    return 0;
}

static int mpu6050_read(int fd, int16_t *ax, int16_t *ay, int16_t *az)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0)
        return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 not detected at 0x%02X on %s\n", MPU6050_ADDR, I2C_BUS);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU6050 initialized at 0x%02X. Reading every %.1f s. Press Ctrl+C to exit.\n",
           MPU6050_ADDR, SAMPLE_PERIOD);

    while (g_running) {
        int16_t ax, ay, az;
        if (mpu6050_read(fd, &ax, &ay, &az) == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d\n", ax, ay, az);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        usleep((useconds_t)(SAMPLE_PERIOD * 1e6));
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2  2
#define GPIO_3  3
#define GPIO_17 17
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int check_validity(int v1, int v2, int v3) {
    if (v1 < 0 || v1 > 1) return 0;
    if (v2 < 0 || v2 > 1) return 0;
    if (v3 < 0 || v3 > 1) return 0;
    return 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL, *line17 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line2 || !line3 || !line17) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0 ||
        gpiod_line_request_output(line3, "gpio-output", 0) < 0 ||
        gpiod_line_request_output(line17, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    for (int cycle = 0; cycle < NUM_CYCLES && keep_running; cycle++) {
        int v1 = gpiod_line_get_value(line2);
        int v2 = gpiod_line_get_value(line3);
        int v3 = gpiod_line_get_value(line17);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Error reading GPIO values.\n");
            goto cleanup;
        }

        if (!check_validity(v1, v2, v3)) {
            fprintf(stderr, "Invalid GPIO values: %d, %d, %d\n", v1, v2, v3);
            goto cleanup;
        }

        printf("Cycle %d: GPIO 2 = %d, GPIO 3 = %d, GPIO 17 = %d\n", cycle + 1, v1, v2, v3);
        fflush(stdout);

        for (int i = 0; i < CYCLE_DELAY_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

