    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i, ret;

    for (i = 0; i < NUM_PINS; i++) lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
