#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. Is the pigpio daemon running?\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int duty_cycle = 500000; // 50% duty cycle (range 0-1000000)
    for (int i = 0; i < num_pins; i++) {
        if (gpioPWM(pins[i], duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM started on GPIO %d, %d, %d, %d with 50%% duty cycle\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
    fflush(stdout);

    while (keep_running) {
        gpioDelay(100000); // 100ms
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(GPIO_2)");
        goto cleanup;
    }
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (line3 == NULL) {
        perror("gpiod_chip_get_line(GPIO_3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line2, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_3)");
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 configured as outputs (initial 0).\n");
    fflush(stdout);

    /* Main loop: toggle both lines every second */
    while (keep_running) {
        int val2 = gpiod_line_get_value(line2);
        int val3 = gpiod_line_get_value(line3);

        if (val2 < 0 || val3 < 0) {
            fprintf(stderr, "Error reading GPIO values (val2=%d, val3=%d).\n", val2, val3);
            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", val2, val3);
        fflush(stdout);

        /* Toggle both lines */
        if (gpiod_line_set_value(line2, val2 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(GPIO_2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, val3 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(GPIO_3)");
            goto cleanup;
        }

        /* Sleep for 1 second, but wake early on signal */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

