#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)
#define IMAGE_FILE "captured_image.jpg"

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device " DEVICE_NAME);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG) {
        fprintf(stderr, "Error: Device does not support JPEG format\n");
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char *buffer = malloc(IMAGE_SIZE);
    if (!buffer) {
        perror("Error allocating buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    if (read(fd, buffer, IMAGE_SIZE) < 0) {
        perror("Error reading image data");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    if (fwrite(buffer, 1, IMAGE_SIZE, fp) != IMAGE_SIZE) {
        perror("Error writing image data to file");
        fclose(fp);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(fp);
    free(buffer);
    close(fd);

    printf("Image captured and saved to %s\n", IMAGE_FILE);
    return EXIT_SUCCESS;
}

