#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define NUM_PIXELS 3
#define CYCLES 3
#define DELAY_US 5000

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    int i, j;
    int red[NUM_PIXELS] = {255, 0, 0};
    int green[NUM_PIXELS] = {0, 255, 0};
    int blue[NUM_PIXELS] = {0, 0, 255};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    for (i = 0; i < CYCLES && keep_running; i++) {
        for (j = 0; j < NUM_PIXELS; j++) {
            if (gpioWrite(GPIO_PIN, red[j]) != 0) {
                fprintf(stderr, "Failed to write red value\n");
                gpioTerminate();
                return 1;
            }
            gpioDelay(DELAY_US);
            if (gpioWrite(GPIO_PIN, green[j]) != 0) {
                fprintf(stderr, "Failed to write green value\n");
                gpioTerminate();
                return 1;
            }
            gpioDelay(DELAY_US);
            if (gpioWrite(GPIO_PIN, blue[j]) != 0) {
                fprintf(stderr, "Failed to write blue value\n");
                gpioTerminate();
                return 1;
            }
            gpioDelay(DELAY_US);
        }
    }

    gpioTerminate();
    return 0;
}

