#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE  "w1_slave"
#define GPIO_PIN       4
#define NUM_READINGS   3
#define READ_INTERVAL  5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(const char *device_path, float *temperature) {
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%s", device_path, W1_SLAVE_FILE);

    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", filename, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);

    char *token = strstr(buffer, "t=");
    if (token == NULL) {
        fprintf(stderr, "Error: 't=' not found in %s\n", filename);
        return -1;
    }

    long raw = strtol(token + 2, NULL, 10);
    *temperature = (float)raw / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    char device_path[256];
    snprintf(device_path, sizeof(device_path), "%s/w1c4", W1_DEVICES_DIR);

    if (access(device_path, F_OK) != 0) {
        fprintf(stderr, "Error: DS18B20 device not found at %s: %s\n", device_path, strerror(errno));
        return 1;
    }

    printf("Starting DS18B20 temperature readings on GPIO %d...\n", GPIO_PIN);
    printf("Press Ctrl+C to exit early.\n");

    for (int i = 0; i < NUM_READINGS && g_running; i++) {
        float temperature;
        if (read_temperature(device_path, &temperature) == 0) {
            printf("Reading %d: %.2f C\n", i + 1, temperature);
        } else {
            fprintf(stderr, "Error reading temperature for reading %d\n", i + 1);
        }
        if (i < NUM_READINGS - 1 && g_running) {
            sleep(READ_INTERVAL);
        }
    }

    printf("\nExiting.\n");
    return 0;
}

