    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    long long start, end, elapsed;

    if (gpiod_line_set_value(trigger, 0) < 0) return -1.0;
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) return -1.0;

    start = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (!running) return -1.0;
        if (now_us() - start > TIMEOUT_US) return -1.0;
    }
    start = now_us();

    while (gpiod_line_get_value(echo) == 1) {
        if (!running) return -1.0;
        if (now_us() - start > TIMEOUT_US) return -1.0;
    }
    end = now_us();

    elapsed = end - start;
    if (elapsed <= 0) return -1.0;

    float distance = (elapsed * SPEED_OF_SOUND_CM_PER_S) / 2000000.0;
    if (distance > MAX_DISTANCE_CM) return -1.0;

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!trigger || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hcsr04-led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance(trigger, echo);

        if (distance < 0.0) {
            printf("Error: measurement failed or out of range.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("gpiod_line_set_value(led on)");
                break;
            }
            usleep(500000);
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value(led off)");
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

