#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 5
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 17};

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    /* Install SIGINT handler so Ctrl+C releases resources cleanly. */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output and set it to 0. */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        values[i] = 0;
    }

    /* Report initial state. */
    printf("Initial state: ");
    for (i = 0; i < NUM_PINS; i++) {
        printf("%u=%d", pins[i], values[i]);
        if (i < NUM_PINS - 1) {
            printf(", ");
        }
    }
    printf("\n");
    fflush(stdout);

    /* Run until SIGINT. */
    while (keep_running) {
        sleep(1);
    }

    /* Release lines and close chip. */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

