static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout) {
    int i = 0;
    while (gpiod_line_get_value(line) != level) {
        if (i++ > timeout) return -1;
        usleep(1);
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int j = 0, counter = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    usleep(500000);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, TIMEOUT) < 0) return -1;
    if (wait_for_level(line, 1, TIMEOUT) < 0) return -1;

    for (int i = 0; i < MAX_TIMINGS && running; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == (i % 2)) {
            counter++;
            usleep(1);
            if (counter == 255) return -1;
        }
        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (!running) return -1;

    if ((j >= 40) && (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
        *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
        *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
        if (data[2] & 0x80) *temperature = -*temperature;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int cycles = 3;
    float temperature, humidity;
    int success = 0;

    for (int i = 0; i < cycles && running; i++) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 1, temperature, humidity);
            success++;
        } else {
            fprintf(stderr, "Cycle %d: DHT22 read failed or data invalid.\n", i + 1);
        }
        if (i < cycles - 1) usleep(2000000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (!running) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    }
    return (success == cycles) ? EXIT_SUCCESS : EXIT_FAILURE;
}

