            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int cycle = 0; cycle < NUM_CYCLES && running; ++cycle) {
        int duty_cycle = (cycle + 1) * 100;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
        }

        printf("Cycle %d: PWM set to %d%%\n", cycle + 1, duty_cycle);
        fflush(stdout);

        for (int s = 0; s < CYCLE_DURATION && running; ++s) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

