#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define DHT22_PIN2 17
#define MAX_TIMINGS 85
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define DHT22_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_ms) {
    int i;
    for (i = 0; i < timeout_ms; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == level) return i;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, struct gpiod_line *line2, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int j = 0;
    int counter = 0;
    int i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    if (gpiod_line_request_output(line2, "dht22", 1) < 0) return -1;

    usleep(1000000);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;
    if (gpiod_line_request_input(line2, "dht22") < 0) return -1;

    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(20000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    int timeout = 1000000;
    while (gpiod_line_get_value(line) == 1 && timeout > 0) {
        usleep(1);
        timeout--;
    }
    if (timeout == 0) return -1;

    timeout = 1000000;
    while (gpiod_line_get_value(line) == 0 && timeout > 0) {
        usleep(1);
        timeout--;
    }
    if (timeout == 0) return -1;

    timeout = 1000000;
    while (gpiod_line_get_value(line) == 1 && timeout > 0) {
        usleep(1);
        timeout--;
    }
    if (timeout == 0) return -1;

    for (i = 0; i < MAX_TIMINGS; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate) {
            counter++;
            usleep(1);
            if (counter == 255) return -1;
        }
        laststate = gpiod_line_get_value(line);
        if (counter == 0) continue;
        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if ((j >= 40) && (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
        *hum = (float)((data[0] << 8) + data[1]) / 10.0;
        *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
        if (data[2] & 0x80) *temp = -*temp;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL, *line2 = NULL;
    float temp, hum;
    int cycles = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN2);
    if (!line || !line2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running && cycles < 3) {
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_dht22(line, line2, &temp, &hum) == 0) {
                printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n", cycles + 1, temp, hum);
                success = 1;
                break;
            }
            fprintf(stderr, "DHT22 read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
        }
        if (!success) {
            fprintf(stderr, "DHT22 not responding after %d retries. Exiting.\n", MAX_RETRIES);
            goto cleanup;
        }
        cycles++;
        if (running && cycles < 3) {
            for (int s = 0; s < DHT22_INTERVAL && running; s++) {
                sleep(1);
            }
        }
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

