        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    /* Main loop: cycle values every 5 seconds */
    while (keep_running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", pins[i]);
                goto cleanup;
            }
        }
        printf("GPIO states: %d %d %d %d\n", values[0], values[1], values[2], values[3]);
        fflush(stdout);
        sleep(5);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
