#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 27
#define TRIGGER_BCM 4
#define ECHO_BCM 17

#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_US 0.0343
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static double elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (double)(end->tv_sec - start->tv_sec) * 1e6 +
           (double)(end->tv_nsec - start->tv_nsec) / 1e3;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIGGER_BCM);
    if (!trig_line) {
        perror("gpiod_chip_get_line (trigger)");
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_BCM);
    if (!echo_line) {
        perror("gpiod_chip_get_line (echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig_line, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            perror("gpiod_line_set_value (trigger high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            break;
        }

        struct timespec start, end;
        int timeout = 0;

        if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
            perror("clock_gettime");
            break;
        }

        while (running) {
            int val = gpiod_line_get_value(echo_line);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                break;
            }
            if (val == 1) {
                break;
            }
            if (elapsed_us(&start, &start) > TIMEOUT_US) {
                timeout = 1;
                break;
            }
            usleep(10);
        }

        if (!running) break;
        if (timeout) {
            fprintf(stderr, "Timeout waiting for echo start.\n");
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
            perror("clock_gettime");
            break;
        }

        while (running) {
            int val = gpiod_line_get_value(echo_line);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                break;
            }
            if (val == 0) {
                break;
            }
            if (elapsed_us(&start, &start) > TIMEOUT_US) {
                timeout = 1;
                break;
            }
            usleep(10);
        }

        if (!running) break;
        if (timeout) {
            fprintf(stderr, "Timeout waiting for echo end.\n");
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
            perror("clock_gettime");
            break;
        }

        double pulse_us = elapsed_us(&start, &end);
        double distance_cm = (pulse_us * SOUND_SPEED_CM_PER_US) / 2.0;

        if (distance_cm > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance_cm);
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

