#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x03
#define I2C_BUS "/dev/i2c-1"
#define NUM_READINGS 3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, 0xD0, &chip_id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x58)\n", chip_id);
        return -1;
    }

    uint8_t calib[24];
    if (i2c_read_reg8(fd, 0x88, &calib[0]) < 0) return -1;
    if (i2c_read_reg8(fd, 0xA1, &calib[12]) < 0) return -1;

    uint16_t dig_T1 = (uint16_t)calib[0] | ((uint16_t)calib[1] << 8);
    int16_t dig_T2 = (int16_t)((uint16_t)calib[2] | ((uint16_t)calib[3] << 8));
    int16_t dig_T3 = (int16_t)((uint16_t)calib[4] | ((uint16_t)calib[5] << 8));
    uint16_t dig_P1 = (uint16_t)calib[6] | ((uint16_t)calib[7] << 8);
    int16_t dig_P2 = (int16_t)((uint16_t)calib[8] | ((uint16_t)calib[9] << 8));
    int16_t dig_P3 = (int16_t)((uint16_t)calib[10] | ((uint16_t)calib[11] << 8));
    int16_t dig_P4 = (int16_t)((uint16_t)calib[12] | ((uint16_t)calib[13] << 8));
    int16_t dig_P5 = (int16_t)((uint16_t)calib[14] | ((uint16_t)calib[15] << 8));
    int16_t dig_P6 = (int16_t)((uint16_t)calib[16] | ((uint16_t)calib[17] << 8));
    int16_t dig_P7 = (int16_t)((uint16_t)calib[18] | ((uint16_t)calib[19] << 8));
    int16_t dig_P8 = (int16_t)((uint16_t)calib[20] | ((uint16_t)calib[21] << 8));
    int16_t dig_P9 = (int16_t)((uint16_t)calib[22] | ((uint16_t)calib[23] << 8));

    uint8_t ctrl_meas = 0x27;
    uint8_t config = 0x00;
    if (write(fd, &ctrl_meas, 1) != 1) return -1;
    if (write(fd, &config, 1) != 1) return -1;

    return 0;
}

static int bmp280_read(int fd, float *temp, float *press) {
    uint8_t data[6];
    if (write(fd, 0xF7, 1) != 1) return -1;
    if (read(fd, data, 6) != 6) return -1;

    int32_t raw_t = (int32_t)data[3] | ((int32_t)data[4] << 8) | ((int32_t)data[5] << 16);
    int32_t raw_p = (int32_t)data[0] | ((int32_t)data[1] << 8) | ((int32_t)data[2] << 16);

    uint8_t calib[24];
    if (i2c_read_reg8(fd, 0x88, &calib[0]) < 0) return -1;
    if (i2c_read_reg8(fd, 0xA1, &calib[12]) < 0) return -1;

    uint16_t dig_T1 = (uint16_t)calib[0] | ((uint16_t)calib[1] << 8);
    int16_t dig_T2 = (int16_t)((uint16_t)calib[2] | ((uint16_t)calib[3] << 8));
    int16_t dig_T3 = (int16_t)((uint16_t)calib[4] | ((uint16_t)calib[5] << 8));
    uint16_t dig_P1 = (uint16_t)calib[6] | ((uint16_t)calib[7] << 8);
    int16_t dig_P2 = (int16_t)((uint16_t)calib[8] | ((uint16_t)calib[9] << 8));
    int16_t dig_P3 = (int16_t)((uint16_t)calib[10] | ((uint16_t)calib[11] << 8));
    int16_t dig_P4 = (int16_t)((uint16_t)calib[12] | ((uint16_t)calib[13] << 8));
    int16_t dig_P5 = (int16_t)((uint16_t)calib[14] | ((uint16_t)calib[15] << 8));
    int16_t dig_P6 = (int16_t)((uint16_t)calib[16] | ((uint16_t)calib[17] << 8));
    int16_t dig_P7 = (int16_t)((uint16_t)calib[18] | ((uint16_t)calib[19] << 8));
    int16_t dig_P8 = (int16_t)((uint16_t)calib[20] | ((uint16_t)calib[21] << 8));
    int16_t dig_P9 = (int16_t)((uint16_t)calib[22] | ((uint16_t)calib[23] << 8));

    int32_t var1 = ((((raw_t >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    int32_t var2 = (((((raw_t >> 4) - ((int32_t)dig_T1)) * ((raw_t >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    int32_t t_fine = var1 + var2;
    *temp = (float)((t_fine * 5 + 128) >> 8) / 100.0f;

    int64_t var_p1 = ((int64_t)t_fine) - 128000;
    int64_t var_p2 = var_p1 * var_p1 * (int64_t)dig_P6;
    var_p2 = var_p2 + ((var_p1 * (int64_t)dig_P5) << 17);
    var_p2 = var_p2 + (((int64_t)dig_P4) << 35);
    var_p1 = ((var_p1 * var_p1 * (int64_t)dig_P3) >> 8) + ((var_p1 * (int64_t)dig_P2) << 12);
    var_p1 = (((((int64_t)1) << 47) + var_p1)) * ((int64_t)dig_P1) >> 33;
    if (var_p1 == 0) return -1;
    int64_t p = 1048576 - raw_p;
    p = (((p << 31) - var_p2) * 3125) / var_p1;
    var_p1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var_p2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var_p1 + var_p2) >> 8) + (((int64_t)dig_P7) << 4);
    *press = (float)p / 25600.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }

    float temp, press;
    for (int i = 0; i < NUM_READINGS && g_running; i++) {
        if (bmp280_read(fd, &temp, &press) < 0) {
            fprintf(stderr, "Error reading BMP280: %s\n", strerror(errno));
            close(fd);
