#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL};
    int values[4] = {0, 0, 0, 0};
    int ret = EXIT_FAILURE;

    int gpios[] = {GPIO_17, GPIO_22, GPIO_23, GPIO_24};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_gpios; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", gpios[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d\n", gpios[i]);
            goto cleanup;
        }
    }

    printf("GPIO 17, 22, 23, 24 set to 0\n");
    fflush(stdout);

    while (keep_running) {
        for (int i = 0; i < num_gpios; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", gpios[i]);
                goto cleanup;
            }
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < num_gpios; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

