#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define NUM_READINGS 3
#define READ_INTERVAL_SEC 5

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bme280_read_id(int fd, uint8_t *id) {
    return i2c_read_reg8(fd, BME280_REG_ID, id);
}

static int bme280_reset(int fd) {
    return i2c_write_reg8(fd, BME280_REG_RESET, 0xB6);
}

static int bme280_wait_not_busy(int fd) {
    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg8(fd, BME280_REG_STATUS, &status) < 0) return -1;
        if ((status & 0x01) == 0) return 0;
        usleep(2000);
    }
    return -1;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (bme280_read_id(fd, &id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Unexpected chip ID 0x%02X (expected 0x60)\n", id);
        return -1;
    }
    if (bme280_reset(fd) < 0) {
        fprintf(stderr, "Error: Failed to reset BME280: %s\n", strerror(errno));
        return -1;
    }
    if (bme280_wait_not_busy(fd) < 0) {
        fprintf(stderr, "Error: BME280 reset timed out\n");
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write humidity control: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error: Failed to write config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_read_data(int fd, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_burst(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error: Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_hum = (data[6] << 8) | data[7];
    *press = (float)raw_press / 100.0f;
    *temp = (float)raw_temp / 100.0f;
    *hum = (float)raw_hum / 1024.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("BME280 initialized successfully.\n");

    for (int i = 0; i < NUM_READINGS && g_running; i++) {
        float temp, hum, press;
        if (bme280_read_data(fd, &temp, &hum, &press) == 0) {
            printf("Reading %d: Temperature = %.2f C, Humidity = %.2f %%, Pressure = %.2f hPa\n", i + 1, temp, hum, press);
        } else {
            fprintf(stderr, "Error: Failed to read data from BME280\n");
        }
        if (i < NUM_READINGS - 1 && g_running) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    close(fd);
    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio-output-demo", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d initialized as output (initial value 0).\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main loop: toggle every second until interrupted */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO %d state: %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
