#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define VEML7700_REG_CONF 0x00
#define VEML7700_REG_DATA 0x04
#define I2C_DEVICE "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Configure VEML7700: 10-bit resolution, 100ms conversion time, no shutdown */
    if (i2c_write_reg8(fd, VEML7700_REG_CONF, 0x00) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, VEML7700_REG_DATA, &raw) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }
        printf("VEML7700: %u\n", raw);
        fflush(stdout);
        usleep(500000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <termios.h>

#define BAUD_RATE B9600
#define PORT "/dev/ttyS0"
#define READ_TIMEOUT_MS 1000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int setup_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = READ_TIMEOUT_MS / 100;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int read_uart_line(int fd, char *buf, size_t buf_size) {
    size_t total = 0;
    while (total < buf_size - 1) {
        ssize_t n = read(fd, buf + total, 1);
        if (n > 0) {
            total += (size_t)n;
            if (buf[total - 1] == '\n') {
                buf[total] = '\0';
                return (int)total;
            }
        } else if (n == 0) {
            usleep(1000);
        } else {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(1000);
                continue;
            }
            if (errno == EINTR) {
                if (!g_running) return -1;
                continue;
            }
            perror("read");
            return -1;
        }
    }
    buf[buf_size - 1] = '\0';
    return (int)total;
}

int main(void) {
    int fd = -1;
    char line[256];

    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    fd = open(PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (setup_uart(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("UART initialized on %s at 9600 baud.\n", PORT);
    printf("Reading data... (Ctrl+C to exit)\n");

    while (g_running) {
        int n = read_uart_line(fd, line, sizeof(line));
        if (n > 0) {
            printf("Received: %s\n", line);
            fflush(stdout);
        } else if (n == 0) {
            usleep(100000);
        } else {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(100000);
                continue;
            }
            if (errno == EINTR) {
                if (!g_running) break;
                continue;
            }
            perror("read");
            break;
        }
    }

    if (fd != -1) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_NS  30000000L   /* 30 ms max echo wait */
#define POLL_STEP_NS 1000000L  /* 1 ms poll interval */
#define LOOP_DELAY_NS 500000000L /* 0.5 s between readings */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_ns(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

static int wait_for_level(struct gpiod_line *line, int target, long long deadline_ns)
{
    while (gpiod_line_get_value(line) != target) {
        if (now_ns() >= deadline_ns)
            return -1;
        usleep(1);
    }
    return 0;
}

static int read_distance(struct gpiod_line *trig, struct gpiod_line *echo, float *distance)
{
    long long deadline;

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trigger, 0)");
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trigger, 1)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trigger, 0)");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    deadline = now_ns() + TIMEOUT_NS;
    if (wait_for_level(echo, 1, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1;
    }

    long long start = now_ns();

    /* Wait for echo falling edge (timeout) */
    deadline = now_ns() + TIMEOUT_NS;
    if (wait_for_level(echo, 0, deadline) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1;
    }

    long long end = now_ns();
    long long elapsed = end - start;

    /* Speed of sound ~343 m/s => 34300 cm/s; distance = elapsed * 34300 / 2e9 */
    *distance = (float)elapsed * 34300.0f / 2000000000.0f;

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance;

        if (read_distance(trig, echo, &distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Read failed; skipping.\n");
        }

        if (running)
            nanosleep((const struct timespec){0, LOOP_DELAY_NS}, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define POLL_INTERVAL_NS 1000000  /* 1 ms */

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle the output every 1 ms */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Sleep 1 ms using nanosleep for portability */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = POLL_INTERVAL_NS };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && keep_running) {
            /* Retry if interrupted by signal */
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int16_t x, y, z;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t buf[6];
    if (write(fd, (uint8_t[]){DATA_FORMAT}, 1) != 1) {
        perror("write DATA_FORMAT");
        close(fd);
        return EXIT_FAILURE;
    }
    if (write(fd, (uint8_t[]){0x08}, 1) != 1) {
        perror("write DATA_FORMAT value");
        close(fd);
        return EXIT_FAILURE;
    }

    if (write(fd, (uint8_t[]){POWER_CTL}, 1) != 1) {
        perror("write POWER_CTL");
        close(fd);
        return EXIT_FAILURE;
    }
    if (write(fd, (uint8_t[]){0x08}, 1) != 1) {
        perror("write POWER_CTL value");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (read(fd, buf, 6) != 6) {
            perror("read");
            break;
        }
        x = (int16_t)((buf[1] << 8) | buf[0]);
        y = (int16_t)((buf[3] << 8) | buf[2]);
        z = (int16_t)((buf[5] << 8) | buf[4]);
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        fflush(stdout);
        usleep(100000);
    }

    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
