#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 500
#define DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioPWM(PWM_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        printf("PWM on GPIO %d: duty cycle %d/%d\n", PWM_PIN, PWM_DUTY_CYCLE, PWM_RANGE);
        fflush(stdout);
        gpioDelay(DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define BCM_PIN 4
#define BCM_PIN_17 17
#define NUM_CYCLES 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line *line17 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        perror("gpiod_chip_get_line (BCM_PIN)");
        goto cleanup;
    }

    line17 = gpiod_chip_get_line(chip, BCM_PIN_17);
    if (!line17) {
        perror("gpiod_chip_get_line (BCM_PIN_17)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (0) */
    if (gpiod_line_request_output(line, "gpio-cycles", 0) < 0) {
        perror("gpiod_line_request_output (BCM_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio-cycles", 0) < 0) {
        perror("gpiod_line_request_output (BCM_PIN_17)");
        goto cleanup;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        /* Cycle 1: HIGH on BCM_PIN, LOW on BCM_PIN_17 */
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value (BCM_PIN HIGH)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value (BCM_PIN_17 LOW)");
            goto cleanup;
        }
        printf("Cycle %d: BCM_PIN HIGH, BCM_PIN_17 LOW\n", i + 1);
        fflush(stdout);
        usleep(500000); /* 500 ms */

        /* Cycle 2: LOW on BCM_PIN, HIGH on BCM_PIN_17 */
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value (BCM_PIN LOW)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value (BCM_PIN_17 HIGH)");
            goto cleanup;
        }
        printf("Cycle %d: BCM_PIN LOW, BCM_PIN_17 HIGH\n", i + 2);
        fflush(stdout);
        usleep(500000); /* 500 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line) gpiod_line_release(line);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

