#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_PIN2 22
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN2, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty1 = 0;
    int duty2 = 0;

    while (running) {
        if (gpioPWM(PWM_PIN, duty1) != 0) {
            fprintf(stderr, "Failed to write PWM to GPIO %d\n", PWM_PIN);
            break;
        }
        if (gpioPWM(PWM_PIN2, duty2) != 0) {
            fprintf(stderr, "Failed to write PWM to GPIO %d\n", PWM_PIN2);
            break;
        }

        printf("GPIO %d: duty=%d, GPIO %d: duty=%d\n", PWM_PIN, duty1, PWM_PIN2, duty2);
        fflush(stdout);

        duty1 = (duty1 + 1) % PWM_RANGE;
        duty2 = (duty2 + 1) % PWM_RANGE;

        usleep(DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioPWM(PWM_PIN2, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

