#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define STATE_PIN 27

#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define SOUND_SPEED_CORRECTION 0.0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1.0;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1.0;

    struct timespec t_start, t_end;
    int timeout = 0;

    while (gpiod_line_get_value(echo) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &t_start) < 0) return -1.0;
        usleep(1);
        if (clock_gettime(CLOCK_MONOTONIC, &t_end) < 0) return -1.0;
        if ((t_end.tv_sec - t_start.tv_sec) * 1000000 + (t_end.tv_nsec - t_start.tv_nsec) / 1000 > 30000) {
            timeout = 1;
            break;
        }
    }

    if (timeout) return -1.0;

    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &t_start) < 0) return -1.0;
        usleep(1);
        if (clock_gettime(CLOCK_MONOTONIC, &t_end) < 0) return -1.0;
        if ((t_end.tv_sec - t_start.tv_sec) * 1000000 + (t_end.tv_nsec - t_start.tv_nsec) / 1000 > 30000) {
            timeout = 1;
            break;
        }
    }

    if (timeout) return -1.0;

    double time = (t_end.tv_sec - t_start.tv_sec) * 1000000.0 + (t_end.tv_nsec - t_start.tv_nsec) / 1000.0;
    double distance = (time / 1000000.0) * SPEED_OF_SOUND_CM_PER_S / 2.0 * (1.0 + SOUND_SPEED_CORRECTION);
    if (distance > MAX_DISTANCE_CM) return -1.0;
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *state = gpiod_chip_get_line(chip, STATE_PIN);

    if (!trig || !echo || !state) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04-echo") < 0 ||
        gpiod_line_request_output(state, "hcsr04-state", 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int state_val = 0;
    int first_reading = 1;

    while (running) {
        double distance = measure_distance(trig, echo);

        if (distance < 0) {
            if (first_reading) {
                fprintf(stderr, "Error: HC-SR04 not responding or out of range.\n");
                first_reading = 0;
            }
            state_val = 0;
        } else {
            if (first_reading) {
                printf("Distance: %.2f cm\n", distance);
                first_reading = 0;
            }
            state_val = (distance > 200.0) ? 1 : 0;
        }

        if (gpiod_line_set_value(state, state_val) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        usleep(100000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(state);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int duty_cycle = 500000; /* 50% duty cycle (range 0-1000000) */

    if (gpioPWM(PWM_PIN_1, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_2, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_3, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on GPIO %d, %d, %d with duty cycle %d\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, duty_cycle);
    fflush(stdout);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Turn off PWM and release resources */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();

    printf("PWM stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>

#define NUM_PINS 7
const int pins[NUM_PINS] = {17, 18, 22, 23, 24, 25, 27};

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_PINS];
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %d\n", pins[i]);
            for (int j = 0; j < i; j++) gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set value on line %d\n", pins[i]);
            for (int j = 0; j < NUM_PINS; j++) gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to HIGH\n", pins[i]);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 17
#define TRIGGER_BCM 4
#define ECHO_BCM 17
#define TRIGGER_PIN 18
#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_US 0.0343
#define TIMEOUT_US 20000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    long long start, end, elapsed;

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    start = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (!running) return -1.0f;
        if (now_us() - start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0f;
        }
    }
    start = now_us();

    while (gpiod_line_get_value(echo) == 1) {
        if (!running) return -1.0f;
        if (now_us() - start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0f;
        }
    }
    end = now_us();

    elapsed = end - start;
    if (elapsed <= 0) {
        fprintf(stderr, "Invalid elapsed time: %lld\n", (long long)elapsed);
        return -1.0f;
    }

    float distance = (float)elapsed * SOUND_SPEED_CM_PER_US / 2.0f;
    if (distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0f;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance(trigger, echo);
        if (distance < 0.0f) {
            fprintf(stderr, "Measurement failed.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 16
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 500;
    if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on GPIO %d (range=%d, frequency=%d Hz, duty=%d/1000)\n",
           PWM_PIN, PWM_RANGE, PWM_FREQUENCY, duty_cycle);
    fflush(stdout);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped on GPIO %d\n", PWM_PIN);
    fflush(stdout);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x03) < 0) return -1;
    return 0;
}

static int read_tcs34725(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    if (i2c_read_word(fd, TCS34725_RDATA, r) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_GDATA, g) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_BDATA, b) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_CDATA, c) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed (device may be absent)\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t r, g, b, c;
        if (read_tcs34725(fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Read failed; continuing\n");
        } else {
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
            fflush(stdout);
        }
        usleep(500000);
    }

    i2c_write_byte(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "toggle"
#define GPIO_18 18
#define GPIO_23 23
#define INTERVAL_SEC 0.01

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line23 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Pi 3/4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("gpiod_chip_get_line(23)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line23, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(23)");
        goto cleanup;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    int val18 = 0;
    int val23 = 0;

    while (keep_running) {
        val18 = !val18;
        val23 = !val23;

        if (gpiod_line_set_value(line18, val18) < 0) {
            perror("gpiod_line_set_value(18)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line23, val23) < 0) {
            perror("gpiod_line_set_value(23)");
            goto cleanup;
        }

        printf("GPIO 18: %d, GPIO 23: %d\n", val18, val23);
        fflush(stdout);

        usleep((useconds_t)(INTERVAL_SEC * 1000000.0));
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line18) gpiod_line_release(line18);
    if (line23) gpiod_line_release(line23);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 7
static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 23, 24, 27};

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    /* Install SIGINT handler so Ctrl+C releases resources cleanly. */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output and set it to 0. */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output\n", pins[i]);
            goto cleanup;
        }
        values[i] = 0;
    }

    printf("GPIO lines initialized to 0: ");
    for (i = 0; i < NUM_PINS; i++) {
        printf("%u ", pins[i]);
    }
    printf("\n");

    /* Run until SIGINT is received. */
    while (keep_running) {
        sleep(1);
    }

    /* Release lines and close chip. */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, "gpio-output-demo", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle the output every 0.5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("GPIO %d: %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        /* Toggle the output */
        val = val ? 0 : 1;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        /* Sleep for 0.5 seconds, checking keep_running every 100 ms */
        for (int i = 0; i < 5 && keep_running; i++) {
            usleep(100000);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

