#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig_line || !echo_line || !led_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig_line, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "hcsr04-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            goto cleanup;
        }

        long long start = now_us();
        if (start < 0) {
            fprintf(stderr, "Failed to get start time: %s\n", strerror(errno));
            goto cleanup;
        }

        while (running) {
            int val = gpiod_line_get_value(echo_line);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
                goto cleanup;
            }
            if (val == 1) {
                break;
            }
            if (now_us() - start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout: no response from sensor\n");
                goto cleanup;
            }
        }

        long long echo_start = now_us();
        if (echo_start < 0) {
            fprintf(stderr, "Failed to get echo start time: %s\n", strerror(errno));
            goto cleanup;
        }

        while (running) {
            int val = gpiod_line_get_value(echo_line);
            if (val < 0) {
                fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
                goto cleanup;
            }
            if (val == 0) {
                break;
            }
            if (now_us() - echo_start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout: no falling edge\n");
                goto cleanup;
            }
        }

        long long echo_end = now_us();
        if (echo_end < 0) {
            fprintf(stderr, "Failed to get echo end time: %s\n", strerror(errno));
            goto cleanup;
        }

        long long elapsed = echo_end - echo_start;
        double distance = (elapsed / 1000000.0) * 34300.0 / 2.0;

        if (gpiod_line_set_value(led_line, (distance > 0.0 && distance < 400.0) ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set LED: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Distance: %.2f cm\n", distance);
        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

